from cardio_1 import a, G
# C34 — Cancers bronchopulmonaires primitifs (P-02-Pneumologie). Clés absentes du glossaire au 09.10.2026.
a('CBNPC', [('C', 'Cancer'), ('B', 'Bronchique'), ('N', 'Non'), ('P', 'à Petites'), ('C', 'Cellules')], 'Cancer bronchique non à petites cellules', '<p>Groupe qui réunit l’adénocarcinome, le carcinome épidermoïde et le carcinome à grandes cellules, par opposition au carcinome à petites cellules. La distinction commande l’ensemble de la stratégie : tests moléculaires, chirurgie et immunothérapie (OMS 2021 ; ESMO 2025).</p>')
a('CBPC', [('C', 'Cancer'), ('B', 'Bronchique'), ('P', 'à Petites'), ('C', 'Cellules')], 'Cancer bronchique à petites cellules', '<p>Carcinome neuroendocrine de haut grade, au diagnostic d’abord morphologique, de croissance rapide et souvent métastatique au diagnostic. Il est traité par chimiothérapie à base de platine et d’étoposide, avec radiothérapie au stade limité et immunothérapie au stade étendu (ESMO 2021).</p>', 'c34-cbpc')
a('EGFR', [('E', 'Epidermal (épidermique)'), ('G', 'Growth (de croissance)'), ('F', 'Factor (facteur)'), ('R', 'Receptor (récepteur)')], 'Récepteur du facteur de croissance épidermique', '<p>Récepteur membranaire à activité tyrosine-kinase. Ses mutations activatrices les plus fréquentes, la délétion de l’exon 19 et la substitution L858R de l’exon 21, rendent la tumeur dépendante de ce signal et sensible à l’osimertinib.</p>', 'c34-egfr')
a('ALK', [('A', 'Anaplastic (anaplasique)'), ('L', 'Lymphoma (du lymphome)'), ('K', 'Kinase')], 'Kinase du lymphome anaplasique', '<p>Gène d’abord décrit dans le lymphome anaplasique à grandes cellules. Dans l’adénocarcinome bronchique, une fusion de ce gène produit une kinase activée en permanence, cible de l’alectinib (ESMO 2025).</p>', 'c34-egfr')
a('L858R', [('L', 'Leucine (acide aminé remplacé)'), ('858', 'en position 858 de la protéine'), ('R', 'aRginine (acide aminé introduit)')], 'Substitution de la leucine 858 par une arginine dans l’exon 21 du gène EGFR', '<p>Notation d’une mutation ponctuelle : lettre de l’acide aminé d’origine, position dans la protéine, lettre de l’acide aminé nouveau (code international à une lettre, où R désigne l’arginine). C’est, avec la délétion de l’exon 19, l’une des deux mutations sensibilisantes classiques.</p>', 'c34-egfr')
a('TNM', [('T', 'Tumeur primitive'), ('N', 'Nodes (ganglions lymphatiques régionaux)'), ('M', 'Métastases à distance')], 'Classification tumeur, ganglions, métastases', '<p>Système international de stadification des cancers solides, publié par l’UICC. La neuvième édition s’applique au cancer bronchique depuis le 1<sup>er</sup> janvier 2025 ; elle divise N2 en N2a et N2b, et M1c en M1c1 et M1c2.</p>', 'c34-tnm')
a('UICC', [('U', 'Union'), ('I', 'Internationale'), ('C', 'Contre le'), ('C', 'Cancer')], 'Union internationale contre le cancer', '<p>Organisation non gouvernementale basée à Genève qui publie la classification TNM des tumeurs malignes ; la neuvième édition est parue en 2025.</p>')
a('IASLC', [('I', 'International (internationale)'), ('A', 'Association for (association pour)'), ('S', 'the Study of (l’étude du)'), ('L', 'Lung (poumon)'), ('C', 'Cancer')], 'Association internationale pour l’étude du cancer du poumon', '<p>Société savante qui a constitué la base de données internationale à l’origine des révisions TNM du cancer bronchique et qui publie la carte des stations ganglionnaires utilisée pour la stadification.</p>')
a('EBUS', [('E', 'EndoBronchial (endobronchique)'), ('US', 'UltraSound (échographie)')], 'Échoendoscopie bronchique', '<p>Bronchoscopie munie d’une sonde d’échographie, qui permet de ponctionner à l’aiguille, sous contrôle visuel, les ganglions médiastinaux et hilaires au contact de la trachée et des bronches. L’ESMO la recommande pour l’analyse anatomopathologique des ganglions suspects.</p>', 'c34-ebus')
a('TTF-1', [('T', 'Thyroid (thyroïdien)'), ('T', 'Transcription (de transcription)'), ('F', 'Factor (facteur)'), ('1', 'numéro 1')], 'Facteur de transcription thyroïdien 1', '<p>Protéine nucléaire exprimée par l’épithélium thyroïdien et par les pneumocytes. Son marquage immunohistochimique oriente vers l’adénocarcinome lorsque la morphologie seule ne tranche pas.</p>', 'c34-ihc')
a('PTHrP', [('PTH', 'Parathyroid Hormone (hormone parathyroïdienne)'), ('r', 'related (apparentée)'), ('P', 'Peptide')], 'Peptide apparenté à l’hormone parathyroïdienne', '<p>Peptide sécrété par certaines tumeurs, notamment les carcinomes épidermoïdes, qui active le récepteur de la parathormone et provoque une hypercalcémie avec parathormone basse. Il explique environ 80 % des hypercalcémies malignes (Revue médicale suisse 2018).</p>', 'c34-calcium')
a('PACIFIC', [('PACIFIC', 'nom propre de l’essai, non développable lettre à lettre')], 'Essai PACIFIC (durvalumab après chimioradiothérapie, 2017)', '<p>Essai de phase III qui a randomisé 713 patients atteints d’un CBNPC de stade III non résécable, sans progression après chimioradiothérapie concomitante, entre durvalumab pendant un an et placebo. Survie à cinq ans : 42,9 % contre 33,4 %.</p>', 'c34-d-durva')
a('ADAURA', [('ADAURA', 'nom propre de l’essai, non développable lettre à lettre')], 'Essai ADAURA (osimertinib adjuvant, 2020)', '<p>Essai de phase III de l’osimertinib adjuvant pendant trois ans au plus, contre placebo, après résection complète d’un CBNPC porteur d’une mutation EGFR sensibilisante ; il montre un gain de survie globale (rapport de risques 0,49).</p>', 'c34-d-osim')
a('LAURA', [('LAURA', 'nom propre de l’essai, non développable lettre à lettre')], 'Essai LAURA (osimertinib après chimioradiothérapie, 2024)', '<p>Essai de phase III de l’osimertinib contre placebo chez 216 patients porteurs d’une mutation EGFR, au stade III non résécable, sans progression après chimioradiothérapie : survie sans progression médiane de 39,1 mois contre 5,6 mois.</p>', 'c34-d-osim')
a('NELSON', [('NELSON', 'Nederlands-Leuvens Longkanker Screenings Onderzoek (étude néerlando-louvaniste de dépistage du cancer du poumon)')], 'Essai NELSON (dépistage par scanner à faible dose, 2020)', '<p>Essai randomisé néerlandais et belge de dépistage par scanner à faible dose chez des fumeurs et anciens fumeurs de 50 à 74 ans ayant au moins 15 paquets-années ; il a réduit d’au moins 20 % la mortalité par cancer bronchique (ESMO 2025).</p>', 'c34-depistage')
a('KEYNOTE', [('KEYNOTE', 'nom de la série d’essais du pembrolizumab, non développable lettre à lettre')], 'Série d’essais KEYNOTE (pembrolizumab)', '<p>Programme d’essais du pembrolizumab. Dans KEYNOTE-024, chez des patients métastatiques dont la tumeur exprime PD-L1 sur au moins 50 % des cellules, le pembrolizumab seul a doublé la survie à cinq ans par rapport à la chimiothérapie (32 % contre 16 %).</p>', 'c34-d-pembro')
a('CheckMate', [('CheckMate', 'nom de la série d’essais du nivolumab, non développable lettre à lettre')], 'Série d’essais CheckMate (nivolumab)', '<p>Programme d’essais du nivolumab. Dans CheckMate 816, trois cycles de chimiothérapie néoadjuvante associée au nivolumab ont porté la réponse pathologique complète de 2,2 % à 24 % et amélioré la survie globale.</p>', 'c34-perio')
a('AEGEAN', [('AEGEAN', 'nom propre de l’essai, non développable lettre à lettre')], 'Essai AEGEAN (durvalumab périopératoire, 2023)', '<p>Essai de phase III de quatre cycles de chimiothérapie néoadjuvante associée au durvalumab, suivis de durvalumab adjuvant, contre chimiothérapie et placebo, dans le CBNPC résécable ; amélioration de la survie sans événement (rapport de risques 0,68).</p>', 'c34-perio')
# Descripteurs de la classification TNM, 9e édition (IASLC 2024)
for k, d in [('T1a','tumeur de 1 cm au plus'),('T1b','tumeur de plus de 1 cm et de 2 cm au plus'),('T1c','tumeur de plus de 2 cm et de 3 cm au plus'),('T2a','tumeur de plus de 3 cm et de 4 cm au plus, ou envahissant la plèvre viscérale, un lobe adjacent, la bronche souche sans la carène, ou avec atélectasie étendue au hile'),('T2b','tumeur de plus de 4 cm et de 5 cm au plus')]:
    a(k, [('T', 'Tumeur primitive'), (k[1], f'catégorie {k[1]}'), (k[2], f'sous-catégorie {k[2]}')], f'Catégorie {k} de la classification TNM (9e édition)', f'<p>{d[0].upper()+d[1:]} (IASLC, 9e édition, 2024).</p>', 'c34-tnm')
for k, d in [('N0','aucune métastase ganglionnaire régionale'),('N1','métastase dans les ganglions péribronchiques, hilaires ou intrapulmonaires homolatéraux, y compris par extension directe'),('N2','métastase dans les ganglions médiastinaux homolatéraux ou sous-carénaires'),('N3','métastase dans les ganglions médiastinaux ou hilaires controlatéraux, ou scalènes ou sus-claviculaires de l’un ou l’autre côté')]:
    a(k, [('N', 'Nodes (ganglions régionaux)'), (k[1], f'catégorie {k[1]}')], f'Catégorie {k} de la classification TNM (9e édition)', f'<p>{d[0].upper()+d[1:]} (IASLC, 9e édition, 2024).</p>', 'c34-tnm')
for k, d in [('N2a','atteinte d’une seule station ganglionnaire médiastinale homolatérale ou sous-carénaire'),('N2b','atteinte de plusieurs stations ganglionnaires médiastinales homolatérales ou sous-carénaires')]:
    a(k, [('N', 'Nodes (ganglions régionaux)'), ('2', 'catégorie 2, médiastinale homolatérale'), (k[2], 'a : une station' if k[2]=='a' else 'b : plusieurs stations')], f'Catégorie {k} de la classification TNM (9e édition)', f'<p>{d[0].upper()+d[1:]}. Subdivision nouvelle de la 9e édition (IASLC 2024).</p>', 'c34-tnm')
for k, d in [('M0','aucune métastase à distance'),('M1a','nodules tumoraux dans le poumon controlatéral, nodules pleuraux ou péricardiques, ou épanchement pleural ou péricardique malin'),('M1b','métastase extrathoracique unique dans un seul système d’organes, y compris un seul ganglion non régional'),('M1c1','métastases extrathoraciques multiples dans un seul système d’organes'),('M1c2','métastases extrathoraciques multiples dans plusieurs systèmes d’organes')]:
    parts = [('M', 'Métastase à distance'), (k[1], f'catégorie {k[1]}')] + ([(k[2:], f'sous-catégorie {k[2:]}')] if len(k) > 2 else [])
    a(k, parts, f'Catégorie {k} de la classification TNM (9e édition)', f'<p>{d[0].upper()+d[1:]} (IASLC, 9e édition, 2024).</p>', 'c34-tnm')
for k, d in [('IA1', 'tumeur de 1 cm au plus sans atteinte ganglionnaire ni métastase (T1a N0 M0)'), ('IA2', 'tumeur de plus de 1 cm et de 2 cm au plus sans atteinte ganglionnaire ni métastase (T1b N0 M0)'), ('IA3', 'tumeur de plus de 2 cm et de 3 cm au plus sans atteinte ganglionnaire ni métastase (T1c N0 M0)')]:
    a(k, [('I', 'stade I'), ('A', 'sous-groupe A'), (k[2], f'subdivision {k[2]} selon la taille')], f'Stade {k} du cancer bronchique (TNM, 9e édition)', f'<p>Stade défini par une {d}. Les tumeurs périphériques de 2 cm au plus (stades IA1 et IA2) peuvent relever d’une résection infralobaire (ESMO 2025).</p>', 'c34-tnm')
a('T790M', [('T', 'Thréonine (acide aminé remplacé)'), ('790', 'en position 790 de la protéine EGFR'), ('M', 'Méthionine (acide aminé introduit)')], 'Substitution de la thréonine 790 par une méthionine dans l’exon 20 du gène EGFR', '<p>Mutation de résistance acquise aux inhibiteurs de tyrosine-kinase de première génération. L’osimertinib est actif sur l’EGFR porteur de cette mutation (information professionnelle Tagrisso).</p>', 'c34-egfr')
a('IB', [('I', 'stade I'), ('B', 'sous-groupe B')], 'Stade IB du cancer bronchique (TNM, 9e édition)', '<p>Stade défini par une tumeur T2a sans atteinte ganglionnaire ni métastase (T2a N0 M0), c’est-à-dire de plus de 3 cm et de 4 cm au plus, ou envahissant la plèvre viscérale ou la bronche souche. C’est à partir de ce stade que l’ESMO 2025 demande la recherche d’une mutation EGFR avant le traitement adjuvant.</p>', 'c34-tnm')
a('M1c', [('M', 'Métastase à distance'), ('1', 'catégorie 1'), ('c', 'sous-catégorie c : métastases extrathoraciques multiples')], 'Catégorie M1c de la classification TNM', '<p>Métastases extrathoraciques multiples. La 9e édition la divise en M1c1, atteinte d’un seul système d’organes, et M1c2, atteinte de plusieurs systèmes, car le pronostic diffère (IASLC 2024).</p>', 'c34-tnm')
a('PD-L2', [('PD', 'Programmed Death (mort programmée)'), ('L', 'Ligand'), ('2', 'numéro 2')], 'Ligand 2 de la mort programmée', '<p>Second ligand du récepteur PD-1, exprimé surtout par les cellules présentatrices d’antigène. Le pembrolizumab bloque la liaison de PD-1 à PD-L1 et à PD-L2 (information professionnelle Keytruda).</p>', 'c34-checkpoint')
a('22C3', [('22C3', 'nom du clone d’anticorps utilisé pour le marquage, non développable')], 'Test immunohistochimique PD-L1 22C3', '<p>Clone d’anticorps employé pour mesurer l’expression de PD-L1 ; il a servi dans les essais du pembrolizumab. Les tests 22C3, 28-8 et SP263 donnent des résultats comparables (ESMO 2023).</p>', 'c34-pdl1')
a('SP263', [('SP263', 'nom du clone d’anticorps utilisé pour le marquage, non développable')], 'Test immunohistochimique PD-L1 SP263', '<p>Clone d’anticorps employé pour mesurer l’expression de PD-L1, interchangeable avec 22C3 et 28-8 (ESMO 2023).</p>', 'c34-pdl1')
a('SP142', [('SP142', 'nom du clone d’anticorps utilisé pour le marquage, non développable')], 'Test immunohistochimique PD-L1 SP142', '<p>Clone d’anticorps qui marque moins de cellules tumorales que les autres tests ; ses résultats ne sont donc pas interchangeables avec ceux de 22C3, 28-8 ou SP263 (ESMO 2023).</p>', 'c34-pdl1')
a('BRCA2', [('BR', 'BReast (sein)'), ('CA', 'CAncer'), ('2', 'gène numéro 2')], 'Gène 2 de prédisposition au cancer du sein', '<p>Gène de réparation de l’ADN par recombinaison homologue ; ses variants germinaux pathogènes figurent parmi ceux rapportés en excès dans les formes familiales de cancer bronchique (ESMO 2025).</p>')
a('CHEK2', [('CHEK', 'CHEckpoint Kinase (kinase de point de contrôle)'), ('2', 'numéro 2')], 'Kinase de point de contrôle 2', '<p>Kinase qui arrête le cycle cellulaire en cas de lésion de l’ADN ; ses variants germinaux sont associés à un risque accru de plusieurs cancers.</p>')
a('ATM', [('A', 'Ataxia (ataxie)'), ('T', 'Telangiectasia (télangiectasies)'), ('M', 'Mutated (muté)')], 'Gène muté dans l’ataxie-télangiectasie', '<p>Gène qui code une kinase centrale de la réponse aux cassures double brin de l’ADN ; ses variants germinaux augmentent le risque de cancer.</p>')
a('NSCLC', [('N', 'Non'), ('S', 'Small (à petites)'), ('C', 'Cell (cellules)'), ('L', 'Lung (pulmonaire)'), ('C', 'Cancer')], 'Non-small cell lung cancer : cancer bronchique non à petites cellules', '<p>Terme anglais employé dans les titres des recommandations internationales ; il correspond au CBNPC.</p>')
a('NG12', [('NG', 'NICE Guideline (recommandation du NICE)'), ('12', 'numéro 12')], 'Recommandation NG12 du NICE sur la suspicion de cancer', '<p>Recommandation britannique du National Institute for Health and Care Excellence qui fixe les symptômes justifiant une imagerie ou un avis urgent devant une suspicion de cancer, dont le cancer bronchique.</p>')
a('Rami-Porta', [('Rami-Porta', 'nom d’auteur')], 'Ramón Rami-Porta, chirurgien thoracique', '<p>Premier auteur des propositions de l’IASLC qui ont fondé la 9e édition de la classification TNM du cancer bronchique (J Thorac Oncol 2024).</p>')
